insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-08-07','nieuw','Offertes','Zie meteen of er een notitie bij een offerte staat',
   'Op het offertebord staat voortaan een notitie-icoontje op de kaart zodra er iets bij het dossier is opgeschreven, met het aantal erbij als het er meer dan een zijn. Klap je de kaart uit, dan lees je de nieuwste notitie meteen: wie hem plaatste, wanneer en wat er staat. Ook de aantekeningen en offerte-herinneringen uit Bouw7 tellen mee.'),
  ('2026-08-07','verbeterd','Dossiers','Bedragen in de lijstweergave staan voluit',
   'De kolom Bedrag kortte grote bedragen af tot bijvoorbeeld "48K", waardoor je het echte bedrag niet kon zien. Nu staat het volledige bedrag in de kolom.');
